    def test_package_scripts_and_dependencies(self):
        package = json.loads((ROOT / "package.json").read_text(encoding="utf-8"))
        self.assertIn("dev", package["scripts"])
        self.assertIn("build", package["scripts"])
        self.assertIn("tauri", package["scripts"])
        self.assertIn("react", package["dependencies"])
        self.assertIn("echarts", package["dependencies"])

    def test_vite_build_splits_route_and_vendor_chunks(self):
        source = (ROOT / "vite.config.ts").read_text(encoding="utf-8")

        self.assertIn("manualChunks", source)
        self.assertIn("react-vendor", source)
        self.assertIn("chart-vendor", source)
        self.assertIn("chunkSizeWarningLimit: 600", source)
        self.assertIn("node_modules/react", source)
        self.assertIn("node_modules/react-dom", source)
        self.assertIn("node_modules/echarts", source)
        self.assertIn("node_modules/zrender", source)

    def test_settings_config_health_shows_provider_model_release_switch_read_only(self):
        settings = (ROOT / "src" / "routes" / "SettingsConfigHealth.tsx").read_text(encoding="utf-8")

        self.assertIn("runtimeOperatorSummary", settings)
        self.assertIn("providerModelEnablementRows", settings)
        self.assertIn("Provider/model release switch", settings)
        self.assertIn("provider_model_enablement_summary_visible", settings)
        self.assertIn("provider_model_enablement_source_config", settings)
        self.assertIn("provider_model_enablement_configured", settings)
        self.assertIn("provider_model_enablement_effective", settings)
        self.assertIn("provider_model_enablement_requires_live_light", settings)
        self.assertIn("provider_model_enablement_requires_execution_request", settings)
        self.assertIn("provider_model_enablement_requires_promotion", settings)
        self.assertIn("provider_model_enablement_creates_task", settings)
        self.assertIn("provider_model_enablement_creates_provider_model_task", settings)
        self.assertIn("provider_model_enablement_calls_provider_model_now", settings)
        self.assertIn("provider_model_enablement_frontend_writeback_allowed", settings)
        self.assertIn("provider_model_enablement_summary_is_production_evidence", settings)
        self.assertIn("runtime_operator_provider_model_enablement_summary_visible", settings)
        self.assertIn("runtime_operator_provider_model_enablement_requires_live_light", settings)
        self.assertIn("runtime_operator_provider_model_enablement_calls_provider_model_now", settings)
        self.assertNotIn("postBootstrapProviderModelExecutionRequest", settings)
        self.assertNotIn("/api/bootstrap/provider-model-execution-request", settings)

    def test_settings_config_health_shows_runtime_mode_policy_rows_read_only(self):
        settings = (ROOT / "src" / "routes" / "SettingsConfigHealth.tsx").read_text(encoding="utf-8")

        self.assertIn("runtimeModePolicyRows", settings)
        self.assertIn("runtimeModeBoundaryRows", settings)
        self.assertIn("bootstrapStatus.runtime_mode_policy_rows", settings)
        self.assertIn("运行模式安全口径", settings)
        self.assertIn("runtime_mode_policy_rows 只读转发；非 production evidence", settings)
        self.assertIn("这些字段来自配置层 policy row", settings)
        self.assertIn("不写配置、不展示 token/key、不创建 task", settings)
        self.assertIn("不能证明完整 live_light 已实现", settings)
        self.assertIn("cache_get_rule", settings)
        self.assertIn("react_render_rule", settings)
        self.assertIn("ledger_rule", settings)
        self.assertIn("ordinary_entrance_visibility_rule", settings)
        self.assertIn("production_evidence_rule", settings)
        self.assertLess(settings.index("运行模式分层"), settings.index("运行模式安全口径"))
        self.assertLess(settings.index("运行模式安全口径"), settings.index("live_light 配置合同"))
        self.assertNotIn("runtimeModePolicyRows.map((row) => ({ ...row }))", settings)

