    def test_task_panel_polls_fastapi_task_endpoint(self):
        client = (ROOT / "src" / "api" / "client.ts").read_text(encoding="utf-8")
        panel = (ROOT / "src" / "components" / "TaskStatusPanel.tsx").read_text(encoding="utf-8")
        receipt = (ROOT / "src" / "components" / "TaskLaunchReceipt.tsx").read_text(encoding="utf-8")
        boundary = (ROOT / "src" / "components" / "TaskBoundarySummary.tsx").read_text(encoding="utf-8")
        model_strategy_ledger = (ROOT / "src" / "components" / "DeepSeekModelStrategyLedger.tsx").read_text(encoding="utf-8")
        styles = (ROOT / "src" / "styles.css").read_text(encoding="utf-8")

        self.assertIn("/api/tasks", client)
        self.assertIn("/api/tasks/catalog", client)
        self.assertIn("TaskCreationEnvelope", client)
        self.assertIn("/api/tasks/${encodeURIComponent(taskId)}", client)
        self.assertIn("/api/tasks/${encodeURIComponent(taskId)}/cancel", client)
        self.assertIn("/api/tasks/${encodeURIComponent(taskId)}/retry", client)
        self.assertIn("getTask(taskId)", panel)
        self.assertIn("mergeTaskEnvelope", panel)
        self.assertIn("taskLookupError", panel)
        self.assertIn("res.call_ledger", panel)
        self.assertIn("res.warnings", panel)
        self.assertIn("cancelTask", panel)
        self.assertIn("本地取消任务", panel)
        self.assertIn("manual_cancel_from_task_status_panel", panel)
        self.assertIn("不调用 Tushare、DeepSeek 或 GitHub", panel)
        self.assertIn("setInterval", panel)
        self.assertIn("local_fallback", panel)
        self.assertIn("onSuccess", panel)
        self.assertIn('task.status === "success" && onSuccess', panel)
        self.assertIn("任务成功后已通知页面刷新本地回放", panel)
        self.assertIn("这不会创建新 task、不调用 Tushare、DeepSeek 或 GitHub、不执行真实交易", panel)
        self.assertIn("p2WritebackQuickRows", panel)
        self.assertIn('aria-label="task status p2 writeback quick read"', panel)
        self.assertIn("P2 写回速读：普通用户先看 cache、call_ledger、packet 三面是否有本地回放信号", panel)
        self.assertIn("这张表只读任务状态，不创建新 task", panel)
        self.assertIn('写回面: "cache"', panel)
        self.assertIn('写回面: "call_ledger"', panel)
        self.assertIn('写回面: "packet"', panel)
        self.assertIn("页面可刷新 GET cache 回放结果", panel)
        self.assertIn("已回放 ${callLedger.length} 条本地审计记录", panel)
        self.assertIn("task.output_packet_key", panel)
        self.assertIn("不展示凭据值、raw log 或交易动作", panel)
        self.assertIn("不代表生产验收或 14 LTG closeout", panel)
        self.assertLess(
            panel.index('aria-label="task status p2 writeback quick read"'),
            panel.index('aria-label="task status audit details"'),
        )
        self.assertIn("candidateRadarResultReplay", panel)
        self.assertIn('const CANDIDATE_CONFIRM_HREF = "#candidates/candidate-radar-search-quant-projection";', panel)
        self.assertIn("p3ResultReplayRows", panel)
        self.assertIn("p3ResultReplayLinks", panel)
